            ]
          }
        },
        "children": {
          "type": "array",
          "items": { "$ref": "#/$defs/node" },
          "maxItems": 500
        }
      }
    },
    "patches": {
      "type": "object",
      "patternProperties": {
        "^[a-z][a-z0-9-]{1,79}$": { "$ref": "#/$defs/propsPatch" }
      },
      "additionalProperties": false
    },
    "viewRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["view", "state"],
      "properties": {
        "view": { "$ref": "#/$defs/id" },
        "state": { "$ref": "#/$defs/id" }
      }
    },
    "designDocument": {
      "type": "object",
      "additionalProperties": false,
      "required": ["meta", "theme", "assets", "components", "views", "flows"],
      "properties": {
        "meta": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "schema",
            "documentId",
            "projectId",
            "revision",
            "title",
            "createdAt",
            "updatedAt"
          ],
          "properties": {
            "schema": { "const": "prism.design-document.v1" },
            "documentId": { "$ref": "#/$defs/id" },
            "projectId": { "$ref": "#/$defs/id" },
            "revision": { "type": "integer", "minimum": 1 },
            "title": { "type": "string", "minLength": 1, "maxLength": 200 },
            "createdAt": { "type": "string", "format": "date-time" },
            "updatedAt": { "type": "string", "format": "date-time" }
          }
        },
        "theme": {
          "type": "object",
          "additionalProperties": false,
          "required": ["colors", "typography", "space", "breakpoints", "rules"],
          "properties": {
            "colors": {
              "type": "object",
              "additionalProperties": { "type": "string" }
            },
            "typography": {
              "type": "object",
              "additionalProperties": {
                "type": "object",
                "additionalProperties": false,
                "required": ["family", "fallback"],
                "properties": {
                  "family": { "type": "string" },
                  "fallback": { "type": "array", "items": { "type": "string" } },
                  "weight": { "type": "integer", "minimum": 100, "maximum": 900 },
                  "size": { "type": "number", "minimum": 0 },
                  "lineHeight": { "type": "number", "exclusiveMinimum": 0 },
                  "letterSpacing": { "type": "number" }
                }
              }
            },
            "space": {
              "type": "object",
              "additionalProperties": { "type": "number", "minimum": 0 }
            },
            "radius": {
              "type": "object",
              "additionalProperties": { "type": "number", "minimum": 0 }
            },
            "shadow": {
              "type": "object",
              "additionalProperties": { "type": "string" }
            },
            "motion": {
              "type": "object",
              "additionalProperties": { "type": "number", "minimum": 0 }
            },
            "breakpoints": {
              "type": "object",
              "additionalProperties": false,
              "required": ["compact", "regular", "wide"],
              "properties": {
                "compact": { "type": "number" },
                "regular": { "type": "number" },
                "wide": { "type": "number" }
              }
            },
            "rules": {
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": ["subject", "instruction"],
                "properties": {
                  "subject": { "type": "string" },
                  "instruction": { "type": "string" }
                }
              }
            }
          }
        },
        "assets": {
          "type": "object",
          "propertyNames": { "$ref": "#/$defs/id" },
          "additionalProperties": {
            "type": "object",
            "required": ["kind", "artifact", "mediaType", "role"],
            "properties": {
              "kind": { "enum": ["image", "icon", "video", "audio", "font"] },
              "artifact": {
                "type": "string",
                "pattern": "^artifact:sha256:[a-f0-9]{64}$"
              },
              "mediaType": { "type": "string" },
              "role": { "type": "string" },
              "alt": { "type": "string" },
              "ratio": { "type": "string" },
              "fit": { "enum": ["contain", "cover", "fill", "none"] },
              "position": {
                "enum": ["top", "right", "bottom", "left", "center"]
              },
              "artDirection": { "type": "string" }
            },
            "additionalProperties": false
          }
        },
        "components": {
          "type": "object",
          "propertyNames": { "$ref": "#/$defs/id" },
          "additionalProperties": {
            "type": "object",
            "additionalProperties": false,
            "required": ["title", "root"],
            "properties": {
              "title": { "type": "string" },
              "root": { "$ref": "#/$defs/node" },
              "variants": {
                "type": "object",
                "additionalProperties": { "$ref": "#/$defs/patches" }
              }
            }
          }
        },
        "views": {
          "type": "object",
          "minProperties": 1,
          "propertyNames": { "$ref": "#/$defs/id" },
          "additionalProperties": {
            "type": "object",
            "additionalProperties": false,
            "required": ["title", "surface", "root", "states", "responsive"],
            "properties": {
              "title": { "type": "string" },
              "surface": { "enum": ["web", "mobile", "desktop", "tui", "cli"] },
              "root": { "$ref": "#/$defs/node" },
              "initialState": { "$ref": "#/$defs/id" },
              "states": {
                "type": "object",
                "required": ["default"],
                "propertyNames": { "$ref": "#/$defs/id" },
                "additionalProperties": {
                  "type": "object",
                  "additionalProperties": false,
                  "required": ["patches"],
                  "properties": { "patches": { "$ref": "#/$defs/patches" } }
                }
              },
              "responsive": {
                "type": "object",
                "additionalProperties": false,
                "required": ["compact", "regular", "wide"],
                "properties": {
                  "compact": {
                    "type": "object",
                    "required": ["patches"],
                    "properties": { "patches": { "$ref": "#/$defs/patches" } },
                    "additionalProperties": false
                  },
                  "regular": {
                    "type": "object",
                    "required": ["patches"],
                    "properties": { "patches": { "$ref": "#/$defs/patches" } },
                    "additionalProperties": false
                  },
                  "wide": {
                    "type": "object",
                    "required": ["patches"],
                    "properties": { "patches": { "$ref": "#/$defs/patches" } },
                    "additionalProperties": false
                  }
                }
              },
              "mockData": { "type": "object" }
            }
          }
        },
        "flows": {
          "type": "object",
          "propertyNames": { "$ref": "#/$defs/id" },
          "additionalProperties": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "title",
              "goal",
              "start",
              "success",
              "recovery",
              "transitions"
            ],
            "properties": {
              "title": { "type": "string" },
              "goal": { "type": "string" },
              "start": { "$ref": "#/$defs/viewRef" },
              "success": { "$ref": "#/$defs/viewRef" },
              "recovery": {
                "type": "array",
                "items": { "$ref": "#/$defs/viewRef" }
              },
              "transitions": {
                "type": "array",
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "required": ["id", "from", "trigger", "to"],
                  "properties": {
                    "id": { "$ref": "#/$defs/id" },
                    "from": { "$ref": "#/$defs/viewRef" },
                    "trigger": {
                      "type": "object",
                      "additionalProperties": false,
                      "required": ["actor", "action"],
                      "properties": {
                        "actor": { "enum": ["user", "system"] },
                        "action": { "$ref": "#/$defs/id" },
                        "node": { "$ref": "#/$defs/id" }
                      }
                    },
                    "response": { "type": "object" },
                    "to": { "$ref": "#/$defs/viewRef" }
                  }
                }
              }
            }
          }
        }
      }
    },
    "designRequest": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema",
        "projectId",
        "architecture",
        "architectureContent"
      ],
      "properties": {
        "schema": { "const": "prism.design-request.v1" },
        "projectId": { "type": "string", "minLength": 1, "maxLength": 200 },
        "architecture": {
          "type": "object",
          "additionalProperties": false,
          "required": ["artifactId", "contentDigest", "revision"],
          "properties": {
            "artifactId": {
              "type": "string",
              "pattern": "^artifact:sha256:[a-f0-9]{64}$"
            },
            "contentDigest": { "$ref": "#/$defs/digest" },
            "revision": { "type": "integer", "minimum": 1 }
          }
        },
        "architectureContent": { "type": "object" },
        "approvalId": { "type": "string", "minLength": 1, "maxLength": 200 }
      }
    },
    "operation": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["type", "baseRevision", "parentId", "index", "node"],
          "properties": {
            "type": { "const": "node.insert" },
            "baseRevision": { "type": "integer" },
            "parentId": { "$ref": "#/$defs/id" },
            "index": { "type": "integer", "minimum": 0 },
            "node": { "$ref": "#/$defs/node" }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["type", "baseRevision", "nodeId"],
          "properties": {
            "type": { "enum": ["node.remove", "node.duplicate"] },
            "baseRevision": { "type": "integer" },
            "nodeId": { "$ref": "#/$defs/id" },
            "newNodeId": { "$ref": "#/$defs/id" }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["type", "baseRevision", "nodeId", "parentId", "index"],
          "properties": {
            "type": { "const": "node.move" },
            "baseRevision": { "type": "integer" },
            "nodeId": { "$ref": "#/$defs/id" },
            "parentId": { "$ref": "#/$defs/id" },
            "index": { "type": "integer", "minimum": 0 }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["type", "baseRevision", "nodeId", "props"],
          "properties": {
            "type": { "const": "node.props.set" },
            "baseRevision": { "type": "integer" },
            "nodeId": { "$ref": "#/$defs/id" },
            "props": { "$ref": "#/$defs/propsPatch" }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["type", "baseRevision", "nodeId", "props", "viewport"],
          "properties": {
            "type": { "const": "responsive.props.set" },
            "baseRevision": { "type": "integer" },
            "nodeId": { "$ref": "#/$defs/id" },
            "props": { "$ref": "#/$defs/propsPatch" },
            "viewport": { "enum": ["compact", "regular", "wide"] }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["type", "baseRevision", "operations"],
          "properties": {
            "type": { "const": "operation.batch" },
            "baseRevision": { "type": "integer" },
            "operations": {
              "type": "array",
              "minItems": 1,
              "items": { "$ref": "#/$defs/operation" }
            }
          }
        }
      ]
    },
    "baselineManifest": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema",
        "bundleId",
        "projectId",
        "revision",
        "designDocument",
        "designSpecification",
        "acceptanceCriteria",
        "assets",
        "previews",
        "createdAt",
        "digest"
      ],
      "properties": {
        "schema": { "const": "prism.baseline-bundle.v1" },
        "bundleId": { "$ref": "#/$defs/id" },
        "projectId": { "$ref": "#/$defs/id" },
        "revision": { "type": "integer", "minimum": 1 },
        "designDocument": {
          "type": "object",
          "required": ["path", "schema", "revision"]
        },
        "designSpecification": { "type": "object", "required": ["path"] },
