{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://kubeclaw.dev/contracts/plugin-system/v2/plugin-system-v2.schema.json",
  "title": "KubeClaw plugin system v2 contracts",
  "$defs": {
    "namespacedId": {
      "type": "string",
      "pattern": "^[a-z0-9]+(?:[._-][a-z0-9]+)+$",
      "maxLength": 160
    },
    "localId": {
      "type": "string",
      "pattern": "^[a-z0-9]+(?:[._-][a-z0-9]+)*$",
      "maxLength": 96
    },
    "opaqueId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,191}$"
    },
    "relativeModulePath": {
      "type": "string",
      "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+\\.(?:mjs|mts|js|ts)$",
      "maxLength": 512
    },
    "relativeSchemaPath": {
      "type": "string",
      "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+\\.json$",
      "maxLength": 512
    },
    "testContractId": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9._/-]*@[1-9][0-9]*$",
      "maxLength": 256
    },
    "jsonObject": {
      "type": "object"
    },
    "reason": {
      "type": "object",
      "additionalProperties": false,
      "required": ["code"],
      "properties": {
        "code": { "$ref": "#/$defs/namespacedId" },
        "message": { "type": "string", "minLength": 1, "maxLength": 4096 },
        "details": { "$ref": "#/$defs/jsonObject" }
      }
    },
    "packageIdentity": {
      "type": "object",
      "additionalProperties": false,
      "required": ["pluginId", "apiVersion", "packageVersion", "contentDigest"],
      "properties": {
        "pluginId": { "$ref": "#/$defs/namespacedId" },
        "apiVersion": { "const": "pipeline-plugin-v2" },
        "packageVersion": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?$"
        },
        "contentDigest": {
          "type": "string",
          "pattern": "^sha256:[a-f0-9]{64}$"
        }
      }
    },
    "packageResolution": {
      "type": "object",
      "additionalProperties": false,
      "required": ["pluginId", "apiVersion", "packageVersion", "contentDigest", "registrationId"],
      "properties": {
        "pluginId": { "$ref": "#/$defs/namespacedId" },
        "apiVersion": { "const": "pipeline-plugin-v2" },
        "packageVersion": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?$"
        },
        "contentDigest": {
          "type": "string",
          "pattern": "^sha256:[a-f0-9]{64}$"
        },
        "registrationId": { "$ref": "#/$defs/localId" }
      }
    },
    "stageRegistration": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id", "type", "module", "export", "requiredCapabilities",
        "configSchema", "inputSchema", "resultSchema"
      ],
      "properties": {
        "id": { "$ref": "#/$defs/localId" },
        "type": { "$ref": "#/$defs/namespacedId" },
        "module": { "$ref": "#/$defs/relativeModulePath" },
        "export": { "type": "string", "pattern": "^[A-Za-z_$][A-Za-z0-9_$]*$" },
        "requiredCapabilities": {
          "type": "array",
          "items": { "$ref": "#/$defs/namespacedId" },
          "uniqueItems": true
        },
        "configSchema": { "$ref": "#/$defs/relativeSchemaPath" },
        "inputSchema": { "$ref": "#/$defs/relativeSchemaPath" },
        "resultSchema": { "$ref": "#/$defs/relativeSchemaPath" }
      }
    },
    "observerRegistration": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id", "module", "export", "subscriptions", "requiredCapabilities",
        "configSchema", "checkpointSchema", "delivery", "ordering", "failurePolicy"
      ],
      "properties": {
        "id": { "$ref": "#/$defs/localId" },
        "module": { "$ref": "#/$defs/relativeModulePath" },
        "export": { "type": "string", "pattern": "^[A-Za-z_$][A-Za-z0-9_$]*$" },
        "subscriptions": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/namespacedId" }
        },
        "delivery": { "const": "at_least_once" },
        "ordering": { "const": "per_run" },
        "failurePolicy": {
          "type": "object",
          "additionalProperties": false,
          "required": ["mode", "maxAttempts", "backoffMs", "timeoutMs"],
          "properties": {
            "mode": { "enum": ["best_effort", "required"] },
            "maxAttempts": { "type": "integer", "minimum": 1 },
            "backoffMs": { "type": "integer", "minimum": 0 },
            "timeoutMs": { "type": "integer", "minimum": 1 }
          }
        },
        "requiredCapabilities": {
          "type": "array",
          "items": { "$ref": "#/$defs/namespacedId" },
          "uniqueItems": true
        },
        "configSchema": { "$ref": "#/$defs/relativeSchemaPath" },
        "checkpointSchema": { "$ref": "#/$defs/relativeSchemaPath" }
      }
    },
    "adapterRegistration": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id", "module", "export", "providesCapabilities",
        "requiredCapabilities", "configSchema"
      ],
      "properties": {
        "id": { "$ref": "#/$defs/localId" },
        "module": { "$ref": "#/$defs/relativeModulePath" },
        "export": { "type": "string", "pattern": "^[A-Za-z_$][A-Za-z0-9_$]*$" },
        "providesCapabilities": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/namespacedId" }
        },
        "requiredCapabilities": {
          "type": "array",
          "items": { "$ref": "#/$defs/namespacedId" },
          "uniqueItems": true
        },
        "configSchema": { "$ref": "#/$defs/relativeSchemaPath" }
      }
    },
    "testProviderPort": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["name", "kind", "required", "schemaId"],
          "properties": {
            "name": { "$ref": "#/$defs/localId" },
            "kind": { "const": "value" },
            "required": { "type": "boolean" },
            "schemaId": { "$ref": "#/$defs/testContractId" }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["name", "kind", "required", "mediaTypes"],
          "properties": {
            "name": { "$ref": "#/$defs/localId" },
            "kind": { "const": "artifact" },
            "required": { "type": "boolean" },
            "schemaId": { "$ref": "#/$defs/testContractId" },
            "mediaTypes": {
              "type": "array",
              "minItems": 1,
              "maxItems": 32,
              "uniqueItems": true,
              "items": { "type": "string", "minLength": 1, "maxLength": 256 }
            }
          }
        }
      ]
    },
    "testEvidencePolicy": {
      "type": "object",
      "additionalProperties": false,
      "required": ["onPass", "onFail", "onError"],
      "properties": {
        "onPass": {
          "type": "array",
          "maxItems": 128,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/localId" }
        },
        "onFail": {
          "type": "array",
          "maxItems": 128,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/localId" }
        },
        "onError": {
          "type": "array",
          "maxItems": 128,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/localId" }
        }
      }
    },
    "testProviderRegistration": {
      "type": "object",
