        "inputs", "outputs", "requiredCapabilities", "retrySafe",
        "matrixFields", "reportFormats", "evidenceTypes", "evidenceDefaults"
      ],
      "properties": {
        "id": { "$ref": "#/$defs/localId" },
        "contractId": { "$ref": "#/$defs/testContractId" },
        "kind": { "enum": ["test", "fixture"] },
        "module": { "$ref": "#/$defs/relativeModulePath" },
        "export": { "type": "string", "pattern": "^[A-Za-z_$][A-Za-z0-9_$]*$" },
        "configSchema": { "$ref": "#/$defs/relativeSchemaPath" },
        "inputs": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/testProviderPort" }
        },
        "outputs": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/testProviderPort" }
        },
        "requiredCapabilities": {
          "type": "array",
          "maxItems": 128,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/namespacedId" }
        },
        "retrySafe": { "type": "boolean" },
        "matrixFields": {
          "type": "array",
          "maxItems": 64,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/localId" }
        },
        "reportFormats": {
          "type": "array",
          "maxItems": 32,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/localId" }
        },
        "evidenceTypes": {
          "type": "array",
          "maxItems": 128,
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/localId" }
        },
        "evidenceDefaults": { "$ref": "#/$defs/testEvidencePolicy" }
      }
    },
    "reportAdapterRegistration": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "format", "contractVersion", "module", "export", "mediaTypes"],
      "properties": {
        "id": { "$ref": "#/$defs/localId" },
        "format": { "$ref": "#/$defs/localId" },
        "contractVersion": { "type": "integer", "minimum": 1 },
        "module": { "$ref": "#/$defs/relativeModulePath" },
        "export": { "type": "string", "pattern": "^[A-Za-z_$][A-Za-z0-9_$]*$" },
        "mediaTypes": {
          "type": "array",
          "minItems": 1,
          "maxItems": 32,
          "uniqueItems": true,
          "items": { "type": "string", "minLength": 1, "maxLength": 256 }
        }
      }
    },
    "pluginManifest": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "apiVersion", "packageVersion", "stages", "observers", "adapters"],
      "properties": {
        "id": { "$ref": "#/$defs/namespacedId" },
        "apiVersion": { "const": "pipeline-plugin-v2" },
        "packageVersion": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?$"
        },
        "stages": {
          "type": "array",
          "items": { "$ref": "#/$defs/stageRegistration" }
        },
        "observers": {
          "type": "array",
          "items": { "$ref": "#/$defs/observerRegistration" }
        },
        "adapters": {
          "type": "array",
          "items": { "$ref": "#/$defs/adapterRegistration" }
        },
        "testProviders": {
          "type": "array",
          "items": { "$ref": "#/$defs/testProviderRegistration" }
        },
        "reportAdapters": {
          "type": "array",
          "items": { "$ref": "#/$defs/reportAdapterRegistration" }
        }
      },
      "anyOf": [
        { "required": ["stages"], "properties": { "stages": { "type": "array", "minItems": 1 } } },
        { "required": ["observers"], "properties": { "observers": { "type": "array", "minItems": 1 } } },
        { "required": ["adapters"], "properties": { "adapters": { "type": "array", "minItems": 1 } } },
        { "required": ["testProviders"], "properties": { "testProviders": { "type": "array", "minItems": 1 } } },
        { "required": ["reportAdapters"], "properties": { "reportAdapters": { "type": "array", "minItems": 1 } } }
      ]
    },
    "stageDefinition": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "type", "dependsOn", "config", "input", "execution"],
      "properties": {
        "id": { "$ref": "#/$defs/localId" },
        "type": { "$ref": "#/$defs/namespacedId" },
        "dependsOn": {
          "type": "array",
          "items": { "$ref": "#/$defs/localId" },
          "uniqueItems": true
        },
        "config": { "$ref": "#/$defs/jsonObject" },
        "input": { "$ref": "#/$defs/jsonObject" },
        "activation": {
          "type": "object",
          "additionalProperties": false,
          "required": ["sourceStage", "fact", "equals"],
          "properties": {
            "sourceStage": { "$ref": "#/$defs/localId" },
            "fact": { "$ref": "#/$defs/namespacedId" },
            "equals": {
              "oneOf": [
                { "type": "string" },
                { "type": "number" },
                { "type": "boolean" },
                { "type": "null" }
              ]
            }
          }
        },
        "execution": {
          "type": "object",
          "additionalProperties": false,
          "required": ["maxAttempts", "maxRemediationCycles", "timeoutMs"],
