        "runId": { "$ref": "#/$defs/opaqueId" },
        "stageId": { "$ref": "#/$defs/localId" },
        "attemptId": { "$ref": "#/$defs/opaqueId" },
        "attemptNumber": { "type": "integer", "minimum": 1 }
      }
    },
