      "type": "object",
      "additionalProperties": false,
      "required": ["allowedSourceDigests", "verifiedAttestations"],
      "properties": {
        "allowedSourceDigests": {
          "type": "object",
          "additionalProperties": {
            "type": "array",
            "minItems": 1,
            "uniqueItems": true,
            "items": { "type": "string", "pattern": "^sha256:[a-f0-9]{64}$" }
          }
        },
        "verifiedAttestations": {
          "type": "object",
          "propertyNames": { "pattern": "^sha256:[a-f0-9]{64}$" },
          "additionalProperties": { "type": "string", "pattern": "^sha256:[a-f0-9]{64}$" }
        }
      }
    },
    "providers": {
      "type": "object",
      "additionalProperties": { "type": "string", "minLength": 1 }
    },
    "grants": {
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": {
          "type": "object",
          "additionalProperties": true
        }
      }
    },
    "adapters": {
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": true
      }
    },
    "activeAdapters": {
      "type": "array",
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1 }
    },
    "observers": {
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": true
      }
    },
    "isolation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["cgroupRoot"],
      "properties": { "cgroupRoot": { "type": "string", "minLength": 1 } }
    },
    "storageRoot": { "type": "string", "minLength": 1 },
    "shutdownTimeoutMs": { "type": "integer", "minimum": 1 },
    "effectLockTtlMs": { "type": "integer", "minimum": 60000, "maximum": 86400000 },
    "orchestratorIssuerId": { "type": "string", "minLength": 1 },
    "administrativeDecisionIssuers": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["type", "id"],
        "properties": {
          "type": { "enum": ["operator", "administrator"] },
          "id": { "type": "string", "minLength": 1 }
        }
      }
    }
  }
}

