async function syncDirectory(directory: string): Promise<void> {
  const handle = await fs.open(directory, "r");
  try {
    await handle.sync();
  } finally {
    await handle.close();
  }
}
async function durableBlob(
  root: string,
  contentDigest: string,
  bytes: Uint8Array,
