  | 'REGISTRY_CAPABILITY_CONSTRAINT_INVALID'
  | 'REGISTRY_CAPABILITY_DENIED'
  | 'REGISTRY_CAPABILITY_UNREQUESTED'
  | 'REGISTRY_ADAPTER_CYCLE'
  | 'REGISTRY_RESULT_INVALID';

export class RegistryError extends Error {
