function loadLintPolicy(policyPath: string): Record<string, any> {
  if (!path.isAbsolute(policyPath)) fail('policy path', 'must be absolute');
  if (!fs.existsSync(policyPath)) fail('policy path', `does not exist: ${policyPath}`);
  let parsed: unknown;
