  try { source = fs.readFileSync(policyPath, 'utf8'); parsed = JSON.parse(source); }
  catch (error: any) { fail('policy', `invalid JSON: ${(error as Error).message}`); }
  const policy = validateLintPolicy(parsed, policyPath);
