                    "type": "array",
                    "minItems": 1
                  },
                  "maxRecommendations": {
                    "type": "integer",
                    "minimum": 1
                  }
                }
              }
            }
          },
          "else": {
            "type": "object",
            "properties": {
              "simplification": {
                "type": "object",
                "properties": {
                  "enabledRules": {
                    "type": "array",
                    "maxItems": 0
                  },
