                  }
                ]
              },
              "status": {
                "enum": [
                  "added",
                  "modified",
                  "deleted",
                  "renamed",
                  "copied",
                  "type_changed"
                ]
              },
              "previousPath": {
                "allOf": [
                  {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 1024,
                    "pattern": "^\\S(?:[\\s\\S]*\\S)?(?![\\s\\S])"
                  },
                  {
