                  }
                ]
              }
            },
            "allOf": [
              {
                "if": {
                  "properties": {
                    "status": {
                      "enum": [
                        "renamed",
                        "copied"
                      ]
                    }
                  },
                  "required": [
                    "status"
                  ]
                },
                "then": {
                  "required": [
                    "path",
                    "status",
                    "previousPath"
                  ]
                },
                "else": {
                  "not": {
                    "required": [
