        { type: 'object', properties: { scope: { type: 'object', properties: { unknownScope: { const: 'follow_up' } } } } },
        { type: 'object', properties: { verification: { type: 'object', properties: { insufficientFindingEvidence: { const: 'follow_up' } } } } },
      ],
    },
    then: {
      type: 'object',
      properties: {
        followUp: {
          type: 'object',
