          existing.result.resultDigest !== snapshot.resultDigest ||
          canonicalJson(existing.completionIntent) !== canonicalJson(intent) ||
          existing.planId !== (ownerSnapshot?.planId ?? null) ||
          existing.nodeId !== (ownerSnapshot?.nodeId ?? null)
