  capability: string,
  constraints: Readonly<Record<string, unknown>>,
): Readonly<Record<string, readonly string[]>> {
  if (!isKnownCapability(capability)) {
    throw new RegistryError('REGISTRY_CAPABILITY_UNKNOWN', `Unknown capability: ${capability}`);
