                "facts": { "$ref": "#/$defs/decisionFacts" }
              }
            }
          ]
        },
        {
          "allOf": [
            { "$ref": "#/$defs/resultBase" },
            {
              "type": "object",
              "additionalProperties": false,
              "required": ["schemaVersion", "outcome", "reason", "artifacts"],
              "properties": {
                "schemaVersion": { "const": "stage-result.v2" },
