      "type": "object",
      "additionalProperties": false,
      "required": [
        "schemaVersion", "effectId", "idempotencyKey", "attempt",
        "capability", "operation", "resource", "payload", "requestedAt"
      ],
      "properties": {
        "runtimeDispatchProfile": { "$ref": "#/$defs/runtimeDispatchProfile" },
        "schemaVersion": { "const": "effect-request.v2" },
        "effectId": { "$ref": "#/$defs/opaqueId" },
        "idempotencyKey": { "$ref": "#/$defs/effectIdempotencyKey" },
        "deliveryId": { "$ref": "#/$defs/effectDeliveryId" },
