        "capability": { "$ref": "#/$defs/namespacedId" },
        "operation": { "$ref": "#/$defs/localId" },
        "resource": { "$ref": "#/$defs/resourceIdentity" },
        "payload": { "$ref": "#/$defs/jsonObject" },
        "requestedAt": { "type": "string", "format": "date-time" }
      },
      "allOf": [{
        "if": { "properties": { "runtimeDispatchProfile": true }, "required": ["runtimeDispatchProfile"] },
        "then": { "properties": { "capability": { "const": "runtime.dispatch" }, "operation": { "const": "dispatch" }, "resource": { "type": "object", "properties": { "type": { "const": "runtime.agent" } } } } }
      }]
    },
    "effectReceipt": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schemaVersion", "effectId", "idempotencyKey", "adapter",
        "status", "recordedAt"
      ],
      "properties": {
        "schemaVersion": { "const": "effect-receipt.v2" },
        "effectId": { "$ref": "#/$defs/opaqueId" },
        "idempotencyKey": { "$ref": "#/$defs/effectIdempotencyKey" },
        "adapter": { "$ref": "#/$defs/packageResolution" },
        "status": { "enum": ["accepted", "completed", "failed"] },
        "result": { "$ref": "#/$defs/jsonObject" },
        "error": { "$ref": "#/$defs/reason" },
        "recordedAt": { "type": "string", "format": "date-time" }
      },
      "allOf": [
        {
          "if": { "properties": { "status": { "const": "failed" } }, "required": ["status"] },
          "then": {
            "properties": { "error": {} },
            "required": ["error"],
            "not": { "properties": { "result": {} }, "required": ["result"] }
          }
        },
        {
          "if": { "properties": { "status": { "const": "completed" } }, "required": ["status"] },
          "then": { "not": { "properties": { "error": {} }, "required": ["error"] } }
        },
        {
          "if": { "properties": { "status": { "const": "accepted" } }, "required": ["status"] },
          "then": {
            "not": {
              "anyOf": [
                { "properties": { "result": {} }, "required": ["result"] },
                { "properties": { "error": {} }, "required": ["error"] }
              ]
            }
          }
        }
      ]
    },
