    throw new Error('OPENCLAW_RUNTIME_PROMPT_BUDGET_INVALID');
  }
  if (value.deadlineEpochMs !== undefined && !positiveInteger(value.deadlineEpochMs)) {
    throw new Error('OPENCLAW_RUNTIME_PROMPT_BUDGET_INVALID');
