  if (prepared.sliceSnapshots.length > 1) {
    const outputs: ParsedEchoReviewOutput[] = [];
    for (const slice of prepared.sliceSnapshots) outputs.push(await dispatchEcho(stageConfig.agent, slice, policy, context));
